import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { defineConfig } from 'vite';

// The HTML entry points are generated by scripts/pages.ts (pages.json lists them).
const pages = JSON.parse(readFileSync(resolve(__dirname, 'pages.json'), 'utf8')) as string[];

// In development, forward the live data, tiles, API and image proxies to the production site.
const PROD = process.env.RUTAVIVA_DEV_TARGET ?? 'https://rutaviva.aminox.dev';
const proxy = Object.fromEntries(['/live', '/tiles', '/api', '/route', '/cam', '/pict', '/ign'].map((p) => [p, { target: PROD, changeOrigin: true }]));

export default defineConfig({
  build: { target: 'es2022', chunkSizeWarningLimit: 1600, rollupOptions: { input: pages.map((p) => resolve(__dirname, p)) } },
  server: { proxy },
  preview: { proxy },
});
